input.command:
_gs_d() { if command -v gtimeout >/dev/null; then gtimeout 30 "$@"; elif command -v timeout >/dev/null; then timeout 30 "$@"; elif command -v perl >/dev/null; then perl -e 'alarm(shift);exec(@ARGV)' 30 "$@"; else return 125; fi; }
_A=aside; command -v aside >/dev/null || _A=$(command -v ~/.local/bin/aside)
if [ "${GSTACK_SKIP_ASIDE:-}" = "1" ] || [ -z "$_A" ]; then echo "NEEDS_ASIDE"; else _rc=0; _o=$(_gs_d "$_A" repl 'console.log("ASIDE_READY " + pwd)' 2>&1) || _rc=$?; case "$_rc" in 124|142) echo "ASIDE_TIMEOUT: probe deadline exceeded" ;; 125) echo "ASIDE_UNAVAILABLE: bounded probe unavailable" ;; 0) if printf '%s\n' "$_o" | grep -q '^ASIDE_READY '; then echo "READY: $_A"; else echo "ASIDE_NOT_RUNNING: no readiness marker"; fi ;; *) echo "ASIDE_CLI_ERROR: exit $_rc" ;; esac; fi
